+    #[tokio::test]
+    async fn test_server_spawn_idempotency_cache() {
+        let server = Arc::new(DaemonServer::new());
+        let req_id = "spawn-req-idempotency-1".to_string();
+
+        let session1 = server
+            .handle_spawn(&req_id, "default", None, None, 80, 24)
+            .await
+            .expect("first spawn succeeds");
+
+        let session2 = server
+            .handle_spawn(&req_id, "default", None, None, 80, 24)
+            .await
+            .expect("second spawn with same request id succeeds");
+
+        assert_eq!(
+            session1, session2,
+            "Spawn with same clientRequestId must return cached session id"
+        );
